Build a single-file C# console app (.NET 8 or later, no NuGet packages) that demonstrates a transactional outbox with an idempotent consumer and proves the effect happens exactly once even though delivery is at-least-once.

Use this in-memory stand-in for a relational database. `Execute` is serialised and atomic: changes made to the `DbState` passed to `work` are committed only if `work` returns; if it throws, they are discarded. Use **two** instances: one for the order service, one for billing.

```csharp
public sealed class DbState
{
    public Dictionary<Guid, decimal> Orders { get; private init; } = new();
    public List<OutboxRow> Outbox { get; private init; } = new();
    public HashSet<Guid> Inbox { get; private init; } = new();
    public Dictionary<Guid, decimal> Ledger { get; private init; } = new();
    public long NextSequence { get; set; } = 1;
    public DbState Clone() => new() { Orders = new(Orders), Outbox = new(Outbox), Inbox = new(Inbox), Ledger = new(Ledger), NextSequence = NextSequence };
}

public sealed class Database
{
    private readonly object _gate = new();
    private DbState _state = new();
    public T Execute<T>(Func<DbState, T> work)
    {
        lock (_gate) { var draft = _state.Clone(); var result = work(draft); _state = draft; return result; }
    }
}

public sealed record OutboxMessage(long Sequence, Guid MessageId, string Type, string Payload);
public sealed record OutboxRow(OutboxMessage Message, bool Published);
public sealed class BrokerException(string message) : Exception(message);
public interface IBroker { Task PublishAsync(OutboxMessage message, CancellationToken ct); }
```

Implement:

1. **`OrderService.PlaceOrder(Guid orderId, decimal amount) -> bool`**: throws `ArgumentOutOfRangeException` for `amount <= 0`; otherwise, in **one** `Execute`, inserts the order and an `OrderPlaced` outbox row (new `MessageId`, next `Sequence`, payload carrying order id and amount) and returns `true`. Placing an `orderId` that already exists is a client retry: return `false` and write nothing.
2. **`OutboxRelay.PublishPendingAsync(CancellationToken) -> Task<int>`** (constructor takes the orders `Database`, an `IBroker` and a batch size): reads up to `batchSize` unpublished rows in `Sequence` order in a short transaction, publishes them one by one **outside** any transaction, marks each row published in its own transaction **only after** `PublishAsync` returned, and stops the batch at the first `BrokerException` (do not skip ahead). Returns the number marked.
3. **`InboxConsumer.Handle(OutboxMessage) -> bool`** (constructor takes the billing `Database`): in **one** `Execute`, records `MessageId` in `Inbox` and adds the amount to `Ledger[orderId]`; if the id is already in `Inbox`, changes nothing and returns `false`.
4. **`FlakyBroker : IBroker`** with a seeded `Random` and a `Deliveries` counter: about 20% of calls throw `BrokerException` *without* delivering; about 30% deliver to the consumer (call `Handle`, increment `Deliveries`) and *then* throw (lost acknowledgement); the rest deliver and return normally.
5. **`Main`**: place 50 orders with distinct amounts, re-place 5 of them, check that a transaction that throws midway leaves no trace, run the relay until no unpublished rows remain (with an iteration cap), and print `PASS`/`FAIL` for: duplicate `PlaceOrder` is a no-op; one outbox row per order; failed transaction rolls back; all rows published; `Deliveries > 50` (duplicates really happened); `Inbox.Count == 50`; every ledger entry equals its order amount.

Constraints: no `Task.Wait()`/`.Result`; no transaction (no `Execute` call) may span a `PublishAsync` call; avoid reflection-based `System.Text.Json` (file-based apps run with trimming/AOT analysis on); format the payload yourself with `CultureInfo.InvariantCulture`.

en.referenceSolution:
using System.Globalization;

var ordersDb = new Database();
var billingDb = new Database();
var orders = new OrderService(ordersDb);
var consumer = new InboxConsumer(billingDb);
var broker = new FlakyBroker(consumer, seed: 42);
var relay = new OutboxRelay(ordersDb, broker, batchSize: 10);

var placed = new Dictionary<Guid, decimal>();
for (var i = 1; i <= 50; i++)
{
    var id = Guid.NewGuid();
    placed[id] = i * 10m;
    orders.PlaceOrder(id, i * 10m);
}

// Client retries of the first five orders: same order id, must not create new outbox rows.
foreach (var (id, amount) in placed.Take(5))
    Check("duplicate PlaceOrder is a no-op", !orders.PlaceOrder(id, amount));

Check("rejected order leaves no trace", Throws(() => orders.PlaceOrder(Guid.NewGuid(), 0m)));
Check("failed transaction rolls back", RollsBack(ordersDb));
Check("one outbox row per order", ordersDb.Execute(s => s.Outbox.Count) == placed.Count);

var rounds = 0;
while (ordersDb.Execute(s => s.Outbox.Any(r => !r.Published)) && rounds++ < 1_000)
    await relay.PublishPendingAsync(CancellationToken.None);

Check("all outbox rows published", ordersDb.Execute(s => s.Outbox.All(r => r.Published)));
Check("broker delivered duplicates", broker.Deliveries > placed.Count);
Check("each message applied once", billingDb.Execute(s => s.Inbox.Count) == placed.Count);
Check("ledger matches orders", billingDb.Execute(s =>
    placed.All(p => s.Ledger.TryGetValue(p.Key, out var v) && v == p.Value)));
Console.WriteLine($"deliveries={broker.Deliveries}, orders={placed.Count}, relay rounds={rounds}");

static void Check(string name, bool ok) => Console.WriteLine($"{(ok ? "PASS" : "FAIL")} {name}");

static bool RollsBack(Database db)
{
    var before = db.Execute(s => (s.Orders.Count, s.Outbox.Count));
    try
    {
        db.Execute<int>(s =>
        {
            s.Orders[Guid.NewGuid()] = 1m;
            throw new InvalidOperationException("crash before the outbox row is written");
        });
    }
    catch (InvalidOperationException) { }
    return db.Execute(s => (s.Orders.Count, s.Outbox.Count)) == before;
}

static bool Throws(Action a)
{
    try { a(); return false; }
    catch (ArgumentOutOfRangeException) { return true; }
}

public sealed record OutboxMessage(long Sequence, Guid MessageId, string Type, string Payload);

public sealed record OutboxRow(OutboxMessage Message, bool Published);

public sealed record OrderPlaced(Guid OrderId, decimal Amount)
{
    public string ToPayload() => string.Create(CultureInfo.InvariantCulture, $"{OrderId}|{Amount}");

    public static OrderPlaced FromPayload(string payload)
    {
        var parts = payload.Split('|');
        return new OrderPlaced(Guid.Parse(parts[0]), decimal.Parse(parts[1], CultureInfo.InvariantCulture));
    }
}

public sealed class BrokerException(string message) : Exception(message);

public interface IBroker
{
    Task PublishAsync(OutboxMessage message, CancellationToken ct);
}

/// <summary>Stand-in for one relational database: Execute is serialised and atomic.</summary>
public sealed class DbState
{
    public Dictionary<Guid, decimal> Orders { get; private init; } = new();
    public List<OutboxRow> Outbox { get; private init; } = new();
    public HashSet<Guid> Inbox { get; private init; } = new();
    public Dictionary<Guid, decimal> Ledger { get; private init; } = new();
    public long NextSequence { get; set; } = 1;

    public DbState Clone() => new()
    {
        Orders = new(Orders),
        Outbox = new(Outbox),
        Inbox = new(Inbox),
        Ledger = new(Ledger),
        NextSequence = NextSequence,
    };
}

public sealed class Database
{
    private readonly object _gate = new();
    private DbState _state = new();

    public T Execute<T>(Func<DbState, T> work)
    {
        lock (_gate)
        {
            var draft = _state.Clone();
            var result = work(draft); // if work throws, the draft is discarded: rollback
            _state = draft;           // commit
            return result;
        }
    }
}

public sealed class OrderService(Database db)
{
    /// <returns>true if the order was created, false if it already existed (idempotent retry).</returns>
    public bool PlaceOrder(Guid orderId, decimal amount)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(amount);
        return db.Execute(s =>
        {
            if (s.Orders.ContainsKey(orderId)) return false;
            s.Orders[orderId] = amount;
            var message = new OutboxMessage(
                s.NextSequence++,
                Guid.NewGuid(),
                nameof(OrderPlaced),
                new OrderPlaced(orderId, amount).ToPayload());
            s.Outbox.Add(new OutboxRow(message, Published: false)); // same transaction as the order
            return true;
        });
    }
}

public sealed class OutboxRelay(Database db, IBroker broker, int batchSize)
{
    /// <returns>Number of messages published and marked in this pass.</returns>
    public async Task<int> PublishPendingAsync(CancellationToken ct)
    {
        // Short read transaction; never hold a transaction open across a network call.
        var batch = db.Execute(s => s.Outbox
            .Where(r => !r.Published)
            .OrderBy(r => r.Message.Sequence)
            .Take(batchSize)
            .Select(r => r.Message)
            .ToList());

        var published = 0;
        foreach (var message in batch)
        {
            try
            {
                await broker.PublishAsync(message, ct);
            }
            catch (BrokerException)
            {
                break; // keep order: do not skip ahead of an unpublished message
            }

            db.Execute(s =>
            {
                var i = s.Outbox.FindIndex(r => r.Message.MessageId == message.MessageId);
                s.Outbox[i] = s.Outbox[i] with { Published = true };
                return 0;
            });
            published++;
        }

        return published;
    }
}

public sealed class InboxConsumer(Database db)
{
    /// <returns>true if the effect was applied, false if the message was a duplicate.</returns>
    public bool Handle(OutboxMessage message)
    {
        if (message.Type != nameof(OrderPlaced))
            throw new InvalidOperationException($"Unknown message type {message.Type}");

        var evt = OrderPlaced.FromPayload(message.Payload);

        return db.Execute(s =>
        {
            if (!s.Inbox.Add(message.MessageId)) return false; // dedupe and effect commit together
            s.Ledger[evt.OrderId] = s.Ledger.GetValueOrDefault(evt.OrderId) + evt.Amount;
            return true;
        });
    }
}

public sealed class FlakyBroker(InboxConsumer consumer, int seed) : IBroker
{
    private readonly Random _random = new(seed);

    public int Deliveries { get; private set; }

    public Task PublishAsync(OutboxMessage message, CancellationToken ct)
    {
        ct.ThrowIfCancellationRequested();
        var roll = _random.NextDouble();
        if (roll < 0.2) throw new BrokerException("connection refused"); // not delivered

        Deliveries++;
        consumer.Handle(message);

        if (roll < 0.5) throw new BrokerException("ack lost"); // delivered, but the relay thinks it failed
        return Task.CompletedTask;
    }
}

